import{_ as n,l,o as e,c as s,v as o,p as i,x as t,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const y=JSON.parse('{"title":"Dynamo 与反熵","description":"","frontmatter":{"title":"Dynamo 与反熵","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dynamo-anti-entropy.md","filePath":"cs/dynamo-anti-entropy.md","lastUpdated":1789023840000}'),c={name:"cs/dynamo-anti-entropy.md"};function h(u,a,_,A,E,f){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="dynamo-与反熵" tabindex="-1">Dynamo 与反熵 <a class="header-anchor" href="#dynamo-与反熵" aria-label="Permalink to &quot;Dynamo 与反熵&quot;">​</a></h1><div class="epigraph"><p>始终可写：斜向法定人数把字节先落到提示节点，再用 Merkle 反熵与读修复把分叉收回来。</p><footer>—— 据 DeCandia et al., Dynamo: Amazon&#39;s Highly Available Key-value Store, SOSP 2007 整理</footer></div><p>上一课<a href="/cs/quorum-rw">Quorum</a>的严格相交在分区下会拒绝写。Dynamo 选<a href="/cs/cap-pacelc">PACELC</a>的 A 与 L。缺口是<strong>提示移交与修复</strong>：写没到「该在的」副本时，系统如何还不丢、如何终收敛。本课不重写 \\(R+W\\gt n\\) 的证明。后课 LWW 是收敛时的一种打结。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一致性哈希环上每个键 \\(N\\) 个偏好节点。协调者写 \\(W\\) 个、读 \\(R\\) 个。节点失败时 <strong>sloppy quorum</strong>：写进环上后面的活节点，并记 hinted handoff，对方回来再推。偏好集暂时不相交，线性一致放弃。缺口：愈合后如何发现不一致——不能靠全量扫描每次。</p><p>反熵：副本两两比较键的摘要。Merkle 树让子树哈希不同才下降，带宽随差异量而不是全量。读修复：读时发现版本分叉，把合并结果写回。二者一起逼近<a href="/cs/eventual-consistency">最终一致</a>的收敛。</p><p><span class="marginnote">SOSP 2007 论文把 N/R/W、向量时钟、sloppy、Merkle、gossip 成员放在同一系统里。本课抓反熵与提示，成员 gossip 点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写路径：协调者（可以是负载均衡选的任意节点）向偏好节点并行写，凑满 \\(W\\)（含提示）。读路径：凑 \\(R\\)，比版本。后台：反熵会话、提示重放、节点上环后的数据迁入。</p>',9)),(e(),i(m,null,{default:t(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUT%5B%22PUT%22%5D%20--%3E%20SQ%5B%22sloppy%20W%22%5D%0A%20%20SQ%20--%3E%20HINT%5B%22%E6%8F%90%E7%A4%BA%E8%8A%82%E7%82%B9%22%5D%0A%20%20HINT%20--%3E%20HH%5B%22handoff%20%E5%9B%9E%E5%AE%B6%22%5D%0A%20%20GET%5B%22GET%22%5D%20--%3E%20RR%5B%22%E8%AF%BB%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20AE%5B%22Merkle%20%E5%8F%8D%E7%86%B5%22%5D%20--%3E%20CONV%5B%22%E6%94%B6%E6%95%9B%22%5D%0A%20%20RR%20--%3E%20CONV%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>成员变化用 gossip，不必每次写先跑共识配置——这与链式复制的配置主相反。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>向量时钟标并发写：不可比则保留多版本交给应用（购物车合并）。单时间戳 LWW 会静默丢一边——下一课专门钉这个坑。\\(R=1,W=1\\) 延迟最低，分叉最多；\\(R=W=2,N=3\\) 是常见折中，仍不是 ABD。</p><p>反熵不是立即：窗口内读可旧。运维看到的「不一致」是时间与故障的函数。Merkle 树深度与键分区粒度影响比较轮次；树本身要与哈希环分段对齐，否则比较的不是同一键集。</p><p>本课不把 Cassandra/Riak 当新定理，它们是 Dynamo 论文的后裔。也不把对象存储的跨 AZ 异步复制写成 hinted handoff。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CRDT 半格，不展开一致性哈希虚节点（数据结构课已有）。后课默认：AP 键值 = sloppy + 版本 + 反熵；严格相交的寄存器不要冒充 Dynamo。冲突如何自动消掉是 LWW 与 CRDT 的分界。</p><p>始终可写把安全债务推到愈合。债务用版本与反熵还，不用 CAP 口号还。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Sloppy quorum 与提示移交换可用性，放弃读写相交。</li><li>Merkle 反熵与读修复驱动收敛。</li><li>并发写靠版本向量检出，合并规则另课。</li><li>出处：DeCandia et al., SOSP 2007。</li></ul>',10))])}const T=n(c,[["render",h]]);export{y as __pageData,T as default};
